/**
 * In-process metrics registry (T1).
 *
 * The catalog is fixed: exactly the 30 metrics pinned by the runtime-observability
 * spec (§ Metrics catalog). Every label is an allow-list, so user-controlled data
 * cannot become a Prometheus series; `le` is generated by the histogram renderer
 * and is intentionally absent from every definition.
 *
 * The registry is pure: it has no Fastify, game, auth or database dependency and
 * renders deterministic Prometheus text with no I/O.
 */

/** The three Prometheus metric types used by the catalog. */
export type MetricType = 'counter' | 'gauge' | 'histogram';

/** One catalog entry: type, help text, label allow-lists and histogram buckets. */
export interface MetricDefinition {
  readonly type: MetricType;
  readonly help: string;
  readonly labels?: Readonly<Record<string, readonly string[]>>;
  readonly buckets?: readonly number[];
}

