/** A catalog metric name (the fixed 30-name union). */
export type MetricName = keyof typeof CATALOG;

/** The fixed 30-metric catalog, keyed by metric name. */
export const METRIC_DEFINITIONS: Readonly<Record<MetricName, MetricDefinition>> =
  CATALOG;

/** A validated `[labelName, labelValue]` pair. */
type LabelPair = readonly [string, string];

/** One tracked time series (counters/gauges use `value`; histograms use the rest). */
interface Series {
  readonly labels: readonly LabelPair[];
  value: number;
  readonly bucketCounts: number[];
  sum: number;
  count: number;
}

/** Prometheus label-value escaping: backslash, double quote and newline. */
export function escapeLabelValue(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n');
}

function compareStrings(a: string, b: string): number {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

function formatNumber(value: number): string {
  return String(value);
}

function renderLabels(labels: readonly LabelPair[]): string {
  if (labels.length === 0) return '';
  const sorted = [...labels].sort(([a], [b]) => compareStrings(a, b));
  const rendered = sorted
    .map(([name, value]) => `${name}="${escapeLabelValue(value)}"`)
    .join(',');
  return `{${rendered}}`;
}

function seriesKey(labels: readonly LabelPair[]): string {
  return labels.map(([name, value]) => `${name}\u0000${value}`).join('\u0001');
}

function createSeries(definition: MetricDefinition, labels: readonly LabelPair[]): Series {
  return {
    labels,
    value: 0,
    bucketCounts: (definition.buckets ?? []).map(() => 0),
    sum: 0,
    count: 0,
  };
}

function assertFinite(name: MetricName, value: number): void {
  if (!Number.isFinite(value)) {
    throw new Error(`Metric "${name}" value must be a finite number; received "${String(value)}"`);
  }
}

/**
 * A small in-process Prometheus registry.
 *
 * Reads (`render`) are deterministic; writes validate the metric name and every
 * label against the catalog allow-list before touching any series.
 */
export class Metrics {
  private readonly state = new Map<MetricName, Map<string, Series>>();

  constructor() {
    for (const name of Object.keys(METRIC_DEFINITIONS) as MetricName[]) {
      const definition = METRIC_DEFINITIONS[name];
      const series = new Map<string, Series>();
      // Counters, gauges and histograms all start at zero. Labeled metrics have
      // no series until a valid label value is recorded.
      if (definition.labels === undefined) {
        series.set('', createSeries(definition, []));
      }
      this.state.set(name, series);
    }
  }

  /** Increments a counter (or adds a delta to a gauge). */
  inc(name: MetricName, labels?: Record<string, string>, value = 1): void {
    const definition = this.getDefinition(name);
    if (definition.type === 'histogram') {
      throw new Error(`Metric "${name}" is a histogram; use observe`);
    }
    assertFinite(name, value);
    const series = this.getSeries(name, definition, labels);
    series.value += value;
  }

  /** Sets a gauge to an absolute value. */
  set(name: MetricName, value: number, labels?: Record<string, string>): void {
    const definition = this.getDefinition(name);
    if (definition.type !== 'gauge') {
      throw new Error(`Metric "${name}" is not a gauge; use inc or observe`);
    }
    assertFinite(name, value);
    const series = this.getSeries(name, definition, labels);
    series.value = value;
  }

  /** Records one histogram observation. */
  observe(name: MetricName, value: number): void {
    const definition = this.getDefinition(name);
    if (definition.type !== 'histogram') {
      throw new Error(`Metric "${name}" is not a histogram; use inc or set`);
    }
    assertFinite(name, value);
    const series = this.getSeries(name, definition, undefined);
    const buckets = definition.buckets ?? [];
    for (let index = 0; index < buckets.length; index += 1) {
      if (value <= buckets[index]) {
        series.bucketCounts[index] += 1;
      }
    }
    series.sum += value;
    series.count += 1;
  }

  /** Renders the full catalog as deterministic Prometheus text. */
  render(): string {
    const lines: string[] = [];
    const names = (Object.keys(METRIC_DEFINITIONS) as MetricName[]).sort(compareStrings);

    for (const name of names) {
      const definition = METRIC_DEFINITIONS[name];
      lines.push(`# HELP ${name} ${definition.help}`);
      lines.push(`# TYPE ${name} ${definition.type}`);

      const series = [...(this.state.get(name)?.values() ?? [])].sort((a, b) =>
        compareStrings(seriesKey(a.labels), seriesKey(b.labels)),
      );

      for (const sample of series) {
        if (definition.type === 'histogram') {
          const buckets = definition.buckets ?? [];
          for (let index = 0; index < buckets.length; index += 1) {
            lines.push(
              `${name}_bucket${renderLabels([
                ...sample.labels,
                ['le', formatNumber(buckets[index])],
              ])} ${formatNumber(sample.bucketCounts[index])}`,
            );
          }
          lines.push(
            `${name}_bucket${renderLabels([...sample.labels, ['le', '+Inf']])} ${formatNumber(sample.count)}`,
          );
          lines.push(`${name}_sum${renderLabels(sample.labels)} ${formatNumber(sample.sum)}`);
          lines.push(`${name}_count${renderLabels(sample.labels)} ${formatNumber(sample.count)}`);
        } else {
          lines.push(`${name}${renderLabels(sample.labels)} ${formatNumber(sample.value)}`);
        }
      }
    }

    return `${lines.join('\n')}\n`;
  }

  private getDefinition(name: MetricName): MetricDefinition {
    if (!Object.prototype.hasOwnProperty.call(METRIC_DEFINITIONS, name)) {
      throw new Error(`Unknown metric "${name}"`);
    }
    return METRIC_DEFINITIONS[name];
  }

  private getSeries(
    name: MetricName,
    definition: MetricDefinition,
    labels: Record<string, string> | undefined,
  ): Series {
    const validated = validateLabels(name, definition, labels);
    const key = seriesKey(validated);
    // The constructor initialises every catalog name, and `getDefinition`
    // already validated `name`, so the map is always present.
    const map = this.state.get(name) as Map<string, Series>;
    let series = map.get(key);
    if (series === undefined) {
      series = createSeries(definition, validated);
      map.set(key, series);
    }
    return series;
  }
}

function validateLabels(
  name: MetricName,
  definition: MetricDefinition,
  labels: Record<string, string> | undefined,
): LabelPair[] {
  const declaredLabels: Readonly<Record<string, readonly string[]>> =
    definition.labels ?? {};
  const declared = Object.keys(declaredLabels);
  const provided = labels ?? {};

  for (const labelName of Object.keys(provided)) {
    if (!declared.includes(labelName)) {
      throw new Error(`Metric "${name}" has no label "${labelName}"`);
    }
  }

  const validated: LabelPair[] = [];
  for (const labelName of declared) {
    if (!Object.prototype.hasOwnProperty.call(provided, labelName)) {
      throw new Error(`Metric "${name}" is missing label "${labelName}"`);
    }
    const value = provided[labelName];
    const allowed = declaredLabels[labelName];
    if (!allowed.includes(value)) {
      throw new Error(
        `Metric "${name}" label "${labelName}" has invalid value "${value}"`,
      );
    }
    validated.push([labelName, value]);
  }

  validated.sort(([a], [b]) => compareStrings(a, b));
  return validated;
}

/** Builds an empty registry with the fixed catalog. */
export function createMetrics(): Metrics {
  return new Metrics();
}
